// Nothing: the 21st building.
//
// "You have reached the ontological limit of the ultimate ensemble.
//  You can now make cookies from the void itself."
//
// Greed is punished. Once a game-minute, the void phage may come through your
// Nothings and take something: cookies from your bank, buildings, Nothings
// themselves, an upgrade, an active buff, stock market shares, heavenly chips,
// a sugar lump, or (rarely) a heavenly upgrade.
// The more Nothing you own, and the more of your CpS comes from it, the hungrier
// it gets. Current odds are shown in the building's tooltip.
//
// Vacuum decay (1.2): beyond 100 Nothings the vacuum is metastable. Each game-minute,
// every Nothing past 100 has a small chance of nucleating a bubble of true vacuum.
// If it does, the run ends in a reverse ascension: this run's cookies are erased
// before the ascension counts them, so it earns no prestige and no heavenly chips.
// Everything an ascension keeps is kept. Selling back to 100 makes the vacuum stable.
//
// Built on the game's own systems: Game.Object for the building, Game.TieredUpgrade
// tiers, achievements, and the official mod API for saving. The game keeps mod
// content out of its main save, so removing this mod can't damage your
// vanilla save; Nothing's own data stays stored in case you come back.

(function () {
  'use strict';

  // ---- settings -------------------------------------------------------------
  // Nothing can only be bought by your own clicks, so auto-buyers (Uncanny's
  // auto-buy) can't feed the void for you. Set to false to allow them.
  const MANUAL_BUY_ONLY = true;
  // Chance per Nothing per game-minute that the phage comes through, before greed.
  const PHAGE_BASE = 0.0005;
  // Extra appetite when all of your CpS comes from Nothing: x(1 + PHAGE_GREED).
  const PHAGE_GREED = 3;
  // How the phage chooses what to take (relative weights).
  const LOSS_WEIGHTS = { cookies: 34, building: 22, nothing: 13, upgrade: 10, buff: 8, stock: 4, chips: 5, lumps: 2, heavenly: 2 };
  // Vacuum decay: chance per Nothing beyond the threshold, per game-minute.
  // 0.0001 lets you gamble past 100 for a while; 0.001 makes ~150 a practical wall.
  const DECAY_THRESHOLD = 100;
  const DECAY_CHANCE = 0.0001;

  // ---- constants ------------------------------------------------------------
  const NAME = 'Nothing';
  const MOD_ID = 'nothing';
  const TAG = '[Nothing]';
  const DESC = 'You have reached the ontological limit of the ultimate ensemble. You can now make cookies from the void itself.';

  const TIER_UPGRADES = [
    ['Nothing to see here', 'Move along.'],
    ['Absence of evidence', 'Is not evidence of absence. But it\'s a start.'],
    ['Null and void', 'Contract terminated. Production continues.'],
    ['Null hypothesis', 'Assume nothing. Results: confirmed.'],
    ['Negative space', 'The cookie is just the shape the void leaves around it.'],
    ['Zero-point dough', 'Even at absolute rest, it rises.'],
    ['Ex nihilo', 'Latin for "no receipts."'],
    ['The empty set', 'Contains no cookies. Contains all cookies. The mathematicians are still arguing.'],
    ['Nihil obstat', 'Nothing stands in the way. That\'s the whole job description.'],
    ['The hole truth', 'Nothing but.'],
    ['Horror vacui', 'Nature abhors a vacuum. Nature, it turns out, can be outbid.'],
    ['Nothing personal', 'The void bears you no ill will. It bears nothing at all.'],
    ['Sweet nothings', 'Whispered from the edge of the ensemble. They taste like cookies.'],
    ['Negative proofing', 'The dough rises by ceasing not to exist.'],
    ['Nothing left', 'There\'s nothing left to do but buy more nothing.'],
  ];
  const TIER_ACHIEVEMENTS = [
    ['Something from Nothing', 'Every bakery starts somewhere. Yours started nowhere.'],
    ['A whole lot of nothing', 'And yet the books balance.'],
    ['Nothing much', 'Your accountant has stopped asking.'],
    ['Nothing doing', 'It does, though. Constantly.'],
    ['Next to nothing', 'You keep it on the shelf beside the other nothing.'],
    ['Nothing but net', 'Net profit, specifically. From nothing.'],
    ['All or nothing', 'You chose both.'],
    ['Nothing compares', 'There is no comparison. There is no anything.'],
    ['Good for nothing', 'High praise, in this economy.'],
    ['Nothing is impossible', 'You have checked. It is merely unwise.'],
    ['Nothing short of miraculous', 'Miracles are just nothing with good marketing.'],
    ['Nothing to lose', 'The phage would like a word.'],
    ['Thank you for nothing', 'You\'re welcome.'],
    ['Nothing is certain', 'Except the phage.'],
    ['Nothing at all', 'Congratulations. You have everything.'],
  ];
  const PHAGE_ACHIEVEMENTS = [
    ['Nothing ventured', 'Lose something to the <b>void phage</b>.', 'Nothing gained.', 1],
    ['The abyss gazes also', 'Lose a <b>heavenly upgrade</b> to the void phage.', 'If you gaze long into the oven, the oven gazes also into you.', 2],
    ['Eaten by nothing', 'Have the void phage consume a <b>Nothing</b>.', 'It was always going to.', 3],
  ];
  // 1.1: Nothing's own upgrades beyond the tiers. Saved after the tiers, in this order.
  // price is a multiple of Nothing's base price; icon is a column in the icon sheet's third row.
  const EXTRA_UPGRADES = [
    { name: 'Void fermentation', q: 'Let the emptiness mature.', icon: 0, price: 1e4,
      desc: '<b>Nothings</b> gain <b>+1%</b> CpS for every minute the void phage goes without feeding, up to <b>+100%</b>. The count resets when it feeds.',
      unlock: () => me.amount >= 50 },
    { name: 'Hungry silence', q: 'The gaps between atoms begin to salivate.', icon: 1, price: 1e8,
      desc: '<b>Nothings</b> are <b>three times</b> as efficient.<br>The void phage is <b>50%</b> hungrier.',
      unlock: () => me.amount >= 100 },
    { name: 'Absence management', q: 'Nothing, now at enterprise scale.', icon: 2, price: 1e6,
      desc: 'The void phage is <b>25%</b> less hungry.',
      unlock: () => stats.events >= 10 },
    { name: 'Antibakery', q: 'Whatever it unmakes, it bakes back. Mostly.', icon: 3, price: 1e3,
      desc: 'Whenever the void phage feeds, Nothing bakes back <b>an hour</b> of your CpS.',
      unlock: () => stats.events >= 1 },
    { name: 'Less than nothing', q: 'Now available for less than nothing. Terms and conditions apply.', icon: 4, price: 100,
      desc: '<b>Nothings</b> are <b>10%</b> cheaper.',
      unlock: () => me.amount >= 25 },
  ];
  const BAGEL = { name: 'Black bagels', q: 'Like black holes, but breakfast.', icon: 5, price: 1e5, power: 5, unlock: () => me.amount >= 1 };
  // synergy upgrades in the game's own synergy tiers (they need Synergies Vol. I / Vol. II)
  const SYNERGIES = [
    { name: 'Existential crumbs', q: 'Every clone leaves a little of itself behind. The void collects.', icon: 7, other: 'You', tier: 'synergy1' },
    { name: 'Ontological mildew', q: 'The void grows where thought fails.', icon: 6, other: 'Cortex baker', tier: 'synergy2' },
  ];
  // 1.1 achievements, saved after the first 18. [name, how, quote, icon column, icon row]
  const MORE_ACHIEVEMENTS = [
    ['Nothing to it', 'Buy <b>100</b> Nothings with a single click.', 'Easy.', 2, 0],
    ['No thing, actually', 'Sell all of your Nothing.', 'There was never anything there. You checked.', 9, 2],
    ['Void where prohibited', 'Lose an active <b>buff</b> to the void phage.', 'Offer not valid in this or any universe.', 4, 1],
    ['The bakery at the end of meaning', 'Have <b>Nothing</b> make more than half of your CpS.', 'Open all hours. All of them.', 8, 2],
    ['Less is s\'more', 'Have the void phage consume <b>100</b> Nothings in total.', 'Toast the void. It has been toasting you.', 3, 1],
    // 1.2
    ['Bubble nucleation', 'Trigger a <b>vacuum decay</b>.', 'It was always going to happen somewhere. It happened here.', 10, 2],
    ['Metastable', 'Own <b>200</b> Nothings.', 'Perfectly stable. For now.', 11, 2],
    ['On borrowed time', 'Own more than <b>150</b> Nothings for an hour without the vacuum decaying.', 'Everything seems fine. Everything always seems fine.', 12, 2],
  ];
  const TICKER = [
    'News : local bakery reports record profits from nothing; economists decline to comment, or exist.',
    'News : "it\'s just nothing," insists baker, moments before nothing ate the lab.',
    'News : void phage sighted near cookie supply chain. Authorities urge citizens to stop owning things.',
    'News : philosophers announce the ultimate ensemble is "full." Baker immediately orders more nothing.',
    'News : scientists confirm a troubling increase in locally sourced nothing.',
    'News : several objects reported missing; bakery profits unaffected.',
    'News : philosophers outraged to learn nonexistence has been monetized.',
    'News : vacuum fluctuations unionize, demand better working conditions.',
    'News : astronomers detect a pastry-shaped absence in deep space.',
    'News : grandmas warned not to stare directly into the antimixer.',
    'News : reality downgraded to optional.',
    'News : physicists reassure public that vacuum decay "would be over before anyone noticed." Local baker buys 101st Nothing.',
    'News : universe briefly replaced by a slightly more stable one; residents report no difference, except the bakery is gone.',
  ];

  // Never taken by the phage: switches, selectors and slots whose removal would
  // leave the game in a confused state, plus an upgrade that pays out when bought.
  const HEAVENLY_EXEMPT = new Set(['Legacy', 'Golden switch', 'Shimmering veil', 'Permanent upgrade slot I',
    'Permanent upgrade slot II', 'Permanent upgrade slot III', 'Permanent upgrade slot IV', 'Permanent upgrade slot V',
    'Classic dairy selection', 'Fanciful dairy selection', 'Basic wallpaper assortment',
    'Distinguished wallpaper assortment', 'Golden cookie alert sound', 'Sound test', 'Inspired checklist']);
  const UPGRADE_EXEMPT = new Set(['Chocolate egg']);

  let me = null;
  const ourUpgrades = [];
  const ourAchievements = [];
  let stats = freshStats();
  let urls = null;
  let tick = 0;
  let odds = { perNothing: 0, perMinute: 0, share: 0, decay: 0 };
  let warnedThisRun = false;   // the one-time warning before buying past 100
  let decaying = false;        // between a vacuum decay and the ascension screen

  function freshStats() {
    return { events: 0, cookies: 0, building: 0, nothing: 0, upgrade: 0, buff: 0, stock: 0, chips: 0, lumps: 0, heavenly: 0,
             nothingEaten: 0, sinceFeed: 0, decays: 0, above150: 0 };
  }
  const rand = (a, b) => a + Math.random() * (b - a);
  const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

  // Nothing of ours may stop the game. Cookie Clicker's main loop dies on the first error
  // thrown inside a frame, so everything of ours that runs every frame goes through this:
  // an error is reported once to the console and the frame carries on.
  const failures = {};
  function report(label, e) {
    failures[label] = (failures[label] || 0) + 1;
    if (failures[label] === 1) console.error(TAG + ' ' + label + ' failed; the game carries on.', e);
  }
  function guard(label, fn, fallback) {
    return function () {
      try { return fn.apply(this, arguments); }
      catch (e) { report(label, e); return typeof fallback === 'function' ? fallback.apply(this, arguments) : fallback; }
    };
  }

  // Cookie Monster keeps a table for every building. If it was loaded first, it learns a
  // new building only when the game next recalculates its gains, and if any mod registers
  // before then, its full refresh trips over the stranger and stops the game. So the
  // building goes up first, and the mod registers once Cookie Monster's tables include it.
  const cookieMonsterLoaded = () => !!(window.CookieMonsterData || (Game.mods && (Game.mods.CookieMonster || Game.mods.cookieMonsterMod)));
  function cookieMonsterKnowsAll() {
    const c = window.CookieMonsterData && window.CookieMonsterData.Cache && window.CookieMonsterData.Cache.ObjectsNextAchievement;
    if (!c) return null;                                   // a version that doesn't share its tables
    for (const k in Game.Objects) if (!Object.prototype.hasOwnProperty.call(c, k)) return false;   // own keys: the patch below answers "in"
    return true;
  }
  // Cookie Monster can't take in a building added after it loaded: every one of its
  // refreshes reads its "till next achievement" table for each building before checking
  // whether it should rebuild that table, and a building it hasn't seen isn't in it. Until
  // it has rebuilt the table once with ours, that one table is answered for our name, and
  // nothing else: other objects see the name as absent, and writing it works as usual.
  function shimCookieMonster(name) {
    if (Object.prototype.hasOwnProperty.call(Object.prototype, name)) return null;
    const stub = { TotalNeeded: 0, AmountNeeded: 0, price: 0 };
    Object.defineProperty(Object.prototype, name, {
      configurable: true, enumerable: false,
      get: function () {
        const c = this && Object.prototype.hasOwnProperty.call(this, 'Cursor') ? this.Cursor : null;
        return c && typeof c === 'object' && 'TotalNeeded' in c ? stub : undefined;
      },
      set: function (v) { Object.defineProperty(this, name, { value: v, writable: true, enumerable: true, configurable: true }); },
    });
    return function () { delete Object.prototype[name]; };
  }

  function registerWhenSafe(register) {
    const t0 = Game.T, started = Date.now();
    Game.recalculateGains = 1;
    const wait = setInterval(function () {
      const knows = cookieMonsterLoaded() ? cookieMonsterKnowsAll() : true;
      const settled = Game.T >= t0 + 2 && (knows === true || (knows === null && Date.now() - started > 1000));
      const late = Date.now() - started > 10000;
      if (!settled && !late) { Game.recalculateGains = 1; return; }
      if (late && !settled) console.warn(TAG + ' Cookie Monster has not caught up with the new building; registering anyway.');
      clearInterval(wait);
      register();
    }, 50);
  }

  function dataToBlobUrl(dataUrl) {
    const b64 = dataUrl.split(',')[1];
    const bin = atob(b64); const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return URL.createObjectURL(new Blob([bytes], { type: 'image/png' }));
  }

  // ---- creation ---------------------------------------------------------------
  function create() {
    if (Game.Objects[NAME]) { console.warn(TAG + ' A building named Nothing already exists. Not loading twice.'); return false; }
    const art = window.__NOTHING_ART;
    if (!art) { console.error(TAG + ' Art missing; not loading.'); return false; }

    const names = TIER_UPGRADES.map(t => t[0]).concat(EXTRA_UPGRADES.map(u => u.name), [BAGEL.name], SYNERGIES.map(u => u.name));
    const achNames = TIER_ACHIEVEMENTS.map(t => t[0]).concat(PHAGE_ACHIEVEMENTS.map(t => t[0]), MORE_ACHIEVEMENTS.map(t => t[0]));
    const clash = names.filter(n => Game.Upgrades[n]).concat(achNames.filter(n => Game.Achievements[n]));
    if (clash.length) { console.error(TAG + ' Name clash with existing content, not loading:', clash); return false; }

    urls = { row: dataToBlobUrl(art.row), bg: dataToBlobUrl(art.bg), store: dataToBlobUrl(art.store), icons: dataToBlobUrl(art.icons) };
    Game.Loader.Load([urls.row, urls.bg]);

    // plural-aware string the building tooltip asks for ("%1 nothing" / "%1 nothings")
    if (typeof locStrings !== 'undefined' && !locStrings['%1 nothing']) locStrings['%1 nothing'] = ['%1 nothing', '%1 nothings'];

    // The constructor appends its row by rewriting #rows' innerHTML, which would rebuild
    // every existing row (and break minigame displays). Point it at a scratch container
    // instead, then move the finished row into place.
    const realRows = document.getElementById('rows');
    const scratch = document.createElement('div');
    realRows.id = 'rows-nothing-real';
    scratch.id = 'rows'; scratch.style.display = 'none';
    document.body.appendChild(scratch);
    try {
      me = new Game.Object(NAME, 'nothing|nothings|manifested|[X] deeper abyss|[X] deeper abysses', DESC, 0, 0,
        { pic: urls.row, bg: urls.bg, xV: 8, yV: 96, w: 48, rows: 1, x: 0, y: 0, frames: 4 }, 1,
        function (b) {
          let mult = 1;
          mult *= Game.GetTieredCpsMult(b);
          mult *= Game.magicCpS(b.name);
          if (Game.Has('Hungry silence')) mult *= 3;
          if (Game.Has('Void fermentation')) mult *= 1 + Math.min(100, stats.sinceFeed) / 100;
          return b.baseCps * mult;
        },
        function () { Game.UnlockTiered(this); });
    } finally {
      while (scratch.firstChild) realRows.appendChild(scratch.firstChild);
      scratch.remove();
      realRows.id = 'rows';
    }

    // Price: the game's automatic curve for a 21st building, plus the same kind of
    // late-game jump it gives the last few buildings (You gets x20 too).
    me.basePrice *= 20; me.price = me.basePrice; me.bulkPrice = me.price;
    me.desc = DESC; me.dname = NAME; me.displayName = NAME;

    // row canvas and hover tracking, as the game does for its own buildings
    me.canvas = document.getElementById('rowCanvas' + me.id);
    me.ctx = me.canvas.getContext('2d', { alpha: false });
    me.pics = [];
    AddEvent(me.canvas, 'mouseover', function () { me.mouseOn = true; });
    AddEvent(me.canvas, 'mouseout', function () { me.mouseOn = false; });
    AddEvent(me.canvas, 'mousemove', function (e) { const box = this.getBounds(); me.mousePos[0] = e.pageX - box.left; me.mousePos[1] = e.pageY - box.top; });

    // icon in the "Muted:" bar
    const mute = document.getElementById('buildingsMute');
    if (mute) {
      mute.insertAdjacentHTML('beforeend', '<div class="tinyProductIcon" id="mutedProduct' + me.id + '" style="display:none;background-position:0px 0px;" ' +
        Game.clickStr + '="Game.ObjectsById[' + me.id + '].mute(0);PlaySound(\'snd/clickOn2.mp3\');" ' +
        Game.getDynamicTooltip('Game.mutedBuildingTooltip(' + me.id + ')', 'this') + '></div>');
      document.getElementById('mutedProduct' + me.id).style.backgroundImage = 'url(' + urls.store + ')';
    } else {
      // refresh() expects this element; keep a hidden stand-in if the bar is missing
      const stub = document.createElement('div'); stub.id = 'mutedProduct' + me.id; stub.style.display = 'none'; document.body.appendChild(stub);
    }

    // store entry, added on its own so other buildings' store elements are untouched
    const products = document.getElementById('products');
    const tag = Game.prefs.screenreader ? 'button' : 'div';
    products.insertAdjacentHTML('beforeend', '<' + tag + (Game.prefs.screenreader ? ' aria-labelledby="ariaReader-product-' + me.id + '"' : '') +
      ' class="product toggledOff" ' + Game.getDynamicTooltip('Game.ObjectsById[' + me.id + '].tooltip', 'store') + ' id="product' + me.id + '">' +
      '<div class="icon off" id="productIconOff' + me.id + '" style=""></div><div class="icon" id="productIcon' + me.id + '" style=""></div>' +
      '<div class="content"><div class="lockedTitle">???</div><div class="title productName" id="productName' + me.id + '"></div>' +
      '<span class="priceMult" id="productPriceMult' + me.id + '"></span><span class="price" id="productPrice' + me.id + '"></span>' +
      '<div class="title owned" id="productOwned' + me.id + '"></div>' +
      (Game.prefs.screenreader ? '<label class="srOnly" style="width:64px;left:-64px;" id="ariaReader-product-' + me.id + '"></label>' : '') +
      '</div></' + tag + '>');
    me.l = document.getElementById('product' + me.id);
    AddEvent(me.l, Game.touchEvents ? 'touchend' : 'click', function (e) { Game.ClickProduct(me.id); e.preventDefault(); });
    document.getElementById('productIcon' + me.id).style.backgroundImage = 'url(' + urls.store + ')';
    document.getElementById('productIconOff' + me.id).style.backgroundImage = 'url(' + urls.store + ')';

    // golden cookie "building special" names for this building, so that effect can't crash on it
    if (Game.goldenCookieBuildingBuffs && !Game.goldenCookieBuildingBuffs[NAME]) Game.goldenCookieBuildingBuffs[NAME] = ['Event horizon', 'Heat death'];

    // tiered upgrades: same tiers, prices and doubling as every other building
    TIER_UPGRADES.forEach(function (t, i) {
      const u = Game.TieredUpgrade(t[0], '<q>' + t[1] + '</q>', NAME, i + 1);
      u.pool = ''; u.order = 30000 + i;
      u.icon = [i, 0, urls.icons];
      u.ddesc = BeautifyInText(u.desc);
      ourUpgrades.push(u);
    });

    // achievements for owning Nothing, at the game's usual thresholds
    TIER_ACHIEVEMENTS.forEach(function (t, i) {
      const n = Game.Tiers[i + 1].achievUnlock;
      const a = new Game.Achievement(t[0], 'Have <b>' + Beautify(n) + '</b> ' + (n === 1 ? 'nothing' : 'nothings') + '.<q>' + t[1] + '</q>', [i, 0, urls.icons]);
      a.pool = 'normal'; a.order = 30000 + i;
      a.ddesc = BeautifyInText(a.desc);
      Game.SetTier(NAME, i + 1);
      ourAchievements.push(a);
    });
    PHAGE_ACHIEVEMENTS.forEach(function (t, i) {
      const a = new Game.Achievement(t[0], t[1] + '<q>' + t[2] + '</q>', [t[3], 1, urls.icons]);
      a.pool = 'normal'; a.order = 30100 + i;
      a.ddesc = BeautifyInText(a.desc);
      ourAchievements.push(a);
    });

    // 1.1 upgrades (saved after the tiers, in this order)
    EXTRA_UPGRADES.forEach(function (def, i) {
      const u = new Game.Upgrade(def.name, def.desc + '<q>' + def.q + '</q>', me.basePrice * def.price, [def.icon, 2, urls.icons],
        function () { me.refresh(); Game.storeToRefresh = 1; });
      u.pool = ''; u.order = 30020 + i; u.ddesc = BeautifyInText(u.desc); u.nothingUnlock = def.unlock;
      ourUpgrades.push(u);
    });
    const bagel = Game.NewUpgradeCookie({ name: BAGEL.name, desc: BAGEL.q, icon: [BAGEL.icon, 2, urls.icons], power: BAGEL.power,
      price: me.basePrice * BAGEL.price, locked: true });
    bagel.order = 30030; bagel.ddesc = BeautifyInText(bagel.desc); bagel.nothingUnlock = BAGEL.unlock;
    if (Game.cookieUpgrades && Game.cookieUpgrades.indexOf(bagel) === -1) Game.cookieUpgrades.push(bagel);
    ourUpgrades.push(bagel);
    SYNERGIES.forEach(function (def, i) {
      const u = Game.SynergyUpgrade(def.name, '<q>' + def.q + '</q>', def.other, NAME, def.tier);
      u.pool = ''; u.order = 30040 + i; u.icon = [def.icon, 2, urls.icons]; u.ddesc = BeautifyInText(u.desc);
      ourUpgrades.push(u);
    });
    MORE_ACHIEVEMENTS.forEach(function (t, i) {
      const a = new Game.Achievement(t[0], t[1] + '<q>' + t[2] + '</q>', [t[3], t[4], urls.icons]);
      a.pool = 'normal'; a.order = 30110 + i; a.ddesc = BeautifyInText(a.desc);
      ourAchievements.push(a);
    });

    // Less than nothing: 10% off Nothing, through the game's own building price hook
    const originalModifyPrice = Game.modifyBuildingPrice;
    Game.modifyBuildingPrice = function (building, price) {
      price = originalModifyPrice.call(this, building, price);
      if (building === me && Game.Has('Less than nothing')) price *= 0.9;
      return price;
    };

    // manual purchases only (selling is always allowed)
    const originalBuy = me.buy;
    me.buy = function (amount) {
      if (MANUAL_BUY_ONLY && Game.buyMode !== -1 && !userGesture()) return 0;
      if (Game.buyMode !== -1 && !warnedThisRun) {
        const n = amount || (Game.buyBulk > 0 ? Game.buyBulk : 1);
        if (this.amount + n > DECAY_THRESHOLD) { warnPastThreshold(this.amount + n); return 0; }
      }
      const before = this.amount;
      const result = originalBuy.call(this, amount);
      if (this.amount - before >= 100) Game.Win('Nothing to it');
      if (before > 0 && this.amount === 0) Game.Win('No thing, actually');
      checkUnlocks();
      return result;
    };

    // show the phage's current appetite in the building's tooltip
    const originalTooltip = me.tooltip;
    me.tooltip = guard('tooltip', function () {
      updateOdds();
      // the game draws this tooltip's icon from its own icon sheet by column; point it at ours
      const html = originalTooltip.call(this).replace('<div class="icon" style="float:left;margin-left:-8px;margin-top:-8px;',
        '<div class="icon" style="float:left;margin-left:-8px;margin-top:-8px;background-image:url(\'' + urls.icons + '\');');
      const block = '<div class="line"></div><div class="descriptionBlock" style="color:#d7b8ff;"><b>Void phage:</b> ' +
        (this.amount > 0 ? Beautify(odds.perMinute * 100, 1) + '% chance each minute to consume something.'
          : 'dormant. It wakes when you own Nothing.') +
        (stats.events ? '<br>It has fed ' + Beautify(stats.events) + ' time' + (stats.events === 1 ? '' : 's') + '.' : '') +
        (Game.Has('Void fermentation') ? '<br>Fermenting: <b>+' + Math.min(100, stats.sinceFeed) + '%</b> (' + stats.sinceFeed + ' minute' + (stats.sinceFeed === 1 ? '' : 's') + ' since it last fed).' : '') +
        (MANUAL_BUY_ONLY ? '<br><small>Nothing can only be bought by hand.</small>' : '') + '</div>' +
        '<div class="descriptionBlock" style="color:' + (this.amount > DECAY_THRESHOLD ? '#ff8a7a' : '#9fd8ff') + ';"><b>Vacuum:</b> ' +
        (this.amount > DECAY_THRESHOLD
          ? 'metastable. <b>' + Beautify(odds.decay * 100, 2) + '%</b> chance each minute of vacuum decay, which ends this run with no prestige. Sell back to ' + DECAY_THRESHOLD + ' to make it stable.'
          : 'stable while you own ' + DECAY_THRESHOLD + ' or fewer Nothings.') + '</div>';
      const at = html.lastIndexOf('</div>');
      return at === -1 ? html + block : html.slice(0, at) + block + html.slice(at);
    }, function () { return originalTooltip.call(this); });

    me.refresh();
    return true;
  }

  function decayChanceFor(amount) {
    const excess = Math.max(0, amount - DECAY_THRESHOLD);
    return excess > 0 ? 1 - Math.pow(1 - DECAY_CHANCE, excess) : 0;
  }

  function warnPastThreshold(projected) {
    const pct = Beautify(decayChanceFor(projected) * 100, 2);
    Game.Prompt('<id NothingVacuum><h3>The vacuum is metastable</h3><div class="block">' +
      'Beyond <b>' + DECAY_THRESHOLD + '</b> Nothings, every extra Nothing may nucleate a bubble of true vacuum.' +
      '<div class="line"></div>At <b>' + Beautify(projected) + '</b> Nothings that is a <b>' + pct + '%</b> chance each minute.' +
      ' If it happens, this run ends at once and heaven keeps no record of it: <b>no prestige, no heavenly chips</b>.' +
      ' You keep everything an ascension keeps.<div class="line"></div>Selling back to ' + DECAY_THRESHOLD + ' makes it stable again.' +
      ' You won\'t be asked again this run.</div>',
      [['Buy anyway', 'Game.ClosePrompt();Game.mods.nothing._acceptRisk();Game.ObjectsById[' + me.id + '].buy();'], 'Cancel']);
  }

  function vacuumDecay() {
    if (decaying || Game.OnAscend || Game.AscendTimer > 0) return false;
    decaying = true;
    stats.decays = (stats.decays || 0) + 1; stats.above150 = 0;
    Game.Win('Bubble nucleation');
    const lost = Game.cookiesEarned;
    // erase this run before the ascension counts it: no prestige, no chips, and it
    // doesn't add to your all-time cookies baked either
    Game.cookiesEarned = 0; Game.cookies = 0;
    Game.Notify('Vacuum decay', 'A bubble of true vacuum nucleated among your Nothings and expanded at the speed of light. ' +
      'This universe is gone, along with <b>' + Beautify(lost) + '</b> cookies baked. Heaven has no record of it: this run earned no prestige.',
      [10, 2, urls.icons]);
    console.log(TAG + ' Vacuum decay. ' + Beautify(lost) + ' cookies baked this run were erased before ascending.');
    setTimeout(function () { Game.Ascend(1); }, 0);
    return true;
  }

  function userGesture() {
    const e = window.event;
    return !!(e && e.isTrusted && /^(click|touchend|mouseup|pointerup|keydown)$/.test(e.type));
  }

  // ---- the void phage ------------------------------------------------------------
  function updateOdds() {
    let total = 0;
    for (const b of Game.ObjectsById) total += b.storedTotalCps || 0;
    const share = total > 0 ? (me.storedTotalCps || 0) / total : 0;
    odds.share = share;
    odds.perNothing = PHAGE_BASE * (1 + PHAGE_GREED * share) *
      (Game.Has('Hungry silence') ? 1.5 : 1) * (Game.Has('Absence management') ? 0.75 : 1);
    if (share > 0.5) Game.Win('The bakery at the end of meaning');
    odds.decay = decayChanceFor(me.amount);
    if (me.amount >= 200) Game.Win('Metastable');
    odds.perMinute = me.amount > 0 ? 1 - Math.pow(1 - odds.perNothing, me.amount) : 0;
  }

  const allUpgrades = () => Object.values(Game.UpgradesById);

  function checkUnlocks() {
    // tiers, tier achievements and synergies, even when counts changed without a purchase (e.g. after loading)
    if (me) Game.UnlockTiered(me);
    for (const u of ourUpgrades) {
      if (u.nothingUnlock && !u.unlocked && u.nothingUnlock()) Game.Unlock(u.name);
    }
  }

  function bankMinigame() {
    const bank = Game.Objects['Bank'];
    return bank && bank.minigameLoaded && bank.minigame && bank.minigame.goodsById ? bank.minigame : null;
  }

  function isLeaf(u) {
    for (const v of allUpgrades()) {
      if (!v || v.pool !== 'prestige' || !v.bought || !v.parents) continue;
      for (const p of v.parents) {
        if (p === u || p === u.name) return false;
      }
    }
    return true;
  }

  function lossOptions() {
    const opts = {};
    if (Game.cookies > 0) opts.cookies = true;
    const others = Game.ObjectsById.filter(b => b !== me && b.amount > 0);
    if (others.length) opts.building = others;
    if (me.amount > 0) opts.nothing = true;
    const ups = allUpgrades().filter(u => u && u.bought && (u.pool === '' || u.pool === 'cookie') && !UPGRADE_EXEMPT.has(u.name));
    if (ups.length) opts.upgrade = ups;
    const buffs = Object.values(Game.buffs).filter(b => b && b.time > 0);
    if (buffs.length) opts.buff = buffs;
    const M = bankMinigame();
    if (M) { const goods = Object.values(M.goodsById).filter(g => g && g.stock > 0); if (goods.length) opts.stock = goods; }
    if (Game.lumps >= 1) opts.lumps = true;
    if (Game.heavenlyChips >= 1) opts.chips = true;
    const heav = allUpgrades().filter(u => u && u.pool === 'prestige' && u.bought && !HEAVENLY_EXEMPT.has(u.name) && isLeaf(u));
    if (heav.length) opts.heavenly = heav;
    return opts;
  }

  function phageStrikes(forceType) {
    const opts = lossOptions();
    let type = forceType && opts[forceType] ? forceType : null;
    if (!type) {
      const keys = Object.keys(opts).filter(k => LOSS_WEIGHTS[k] > 0);
      if (!keys.length) return null;
      let roll = Math.random() * keys.reduce((s, k) => s + LOSS_WEIGHTS[k], 0);
      for (const k of keys) { roll -= LOSS_WEIGHTS[k]; if (roll <= 0) { type = k; break; } }
      type = type || keys[keys.length - 1];
    }
    let msg = '';
    if (type === 'cookies') {
      const amt = Game.cookies * rand(0.01, 0.10);
      Game.Spend(amt);
      msg = 'It devoured <b>' + Beautify(amt) + '</b> cookies from your bank.';
    } else if (type === 'building') {
      const b = pick(opts.building);
      const n = Math.max(1, Math.floor(b.amount * rand(0.01, 0.10)));
      b.sacrifice(n);
      if (b.name === 'Grandma') msg = n === 1 ? 'A grandma ceases to have been.' : '<b>' + Beautify(n) + '</b> grandmas cease to have been.';
      else msg = 'It consumed <b>' + Beautify(n) + '</b> ' + (n === 1 ? b.single : b.plural) + '.';
    } else if (type === 'nothing') {
      const n = Math.max(1, Math.floor(me.amount * rand(0.01, 0.10)));
      me.sacrifice(n);
      msg = 'It ate <b>' + Beautify(n) + '</b> of your Nothing. It was always going to.';
      stats.nothingEaten = (stats.nothingEaten || 0) + n;
      Game.Win('Eaten by nothing');
      if (stats.nothingEaten >= 100) Game.Win('Less is s\'more');
    } else if (type === 'upgrade') {
      const u = pick(opts.upgrade);
      u.unearn();
      msg = 'It unmade <b>' + u.dname + '</b>. You can buy it again.';
    } else if (type === 'buff') {
      const buff = pick(opts.buff);
      Game.killBuff(buff.name);
      msg = 'It swallowed your <b>' + (buff.dname || buff.name) + '</b>.';
      Game.Win('Void where prohibited');
    } else if (type === 'stock') {
      const M = bankMinigame(); const g = pick(opts.stock);
      const n = Math.max(1, Math.floor(g.stock * rand(0.10, 0.50)));
      g.stock = Math.max(0, g.stock - n); M.toRedraw = 2;
      msg = 'It erased <b>' + Beautify(n) + '</b> shares of <b>' + g.name + '</b> from your warehouses.';
    } else if (type === 'lumps') {
      Game.lumps = Math.max(0, Game.lumps - 1);
      msg = 'It ate <b>a sugar lump</b>.';
    } else if (type === 'chips') {
      const amt = Math.max(1, Math.floor(Game.heavenlyChips * rand(0.05, 0.25)));
      Game.heavenlyChips = Math.max(0, Game.heavenlyChips - amt);
      msg = 'It drank <b>' + Beautify(amt) + '</b> of your unspent heavenly chips.';
    } else if (type === 'heavenly') {
      const u = pick(opts.heavenly);
      u.unearn();
      msg = 'It tore <b>' + u.dname + '</b> out of the heavens. It\'s gone until you buy it back while ascending.';
      Game.Win('The abyss gazes also');
    }
    stats.events++; stats[type] = (stats[type] || 0) + 1;
    stats.sinceFeed = 0;
    if (Game.Has('Antibakery')) {
      const back = Game.cookiesPs * 3600;
      if (back > 0) { Game.Earn(back); msg += ' Nothing bakes back <b>' + Beautify(back) + '</b> cookies.'; }
    }
    Game.Win('Nothing ventured');
    checkUnlocks();
    Game.recalculateGains = 1; Game.upgradesToRebuild = 1; Game.storeToRefresh = 1;
    Game.Notify('The void phage feeds', msg, [0, 1, urls.icons]);
    console.log(TAG + ' Void phage (' + type + '): ' + msg.replace(/<[^>]+>/g, ''));
    return type;
  }

  function onLogic() {
    if (!me || Game.OnAscend || Game.AscendTimer > 0) return;
    tick++;
    if (tick % (Game.fps * 5) === 0) { updateOdds(); checkUnlocks(); }
    if (tick % (Game.fps * 60) !== 0) return;
    if (me.amount > 0) { stats.sinceFeed++; if (Game.Has('Void fermentation')) Game.recalculateGains = 1; }
    updateOdds();
    if (me.amount > 0 && Math.random() < odds.perMinute) phageStrikes();
    if (me.amount > 150) { stats.above150 = (stats.above150 || 0) + 1; if (stats.above150 >= 60) Game.Win('On borrowed time'); }
    else stats.above150 = 0;
    if (odds.decay > 0 && Math.random() < odds.decay) vacuumDecay();
  }

  // ---- saving ------------------------------------------------------------------
  function recount() {
    let b = 0; for (const o of Game.ObjectsById) b += o.amount;
    Game.BuildingsOwned = b;
    let u = 0; for (const x of Object.values(Game.UpgradesById)) if (x && x.bought && Game.CountsAsUpgradeOwned(x.pool)) u++;
    Game.UpgradesOwned = u;
    let a = 0; for (const i in Game.AchievementsById) { const x = Game.AchievementsById[i]; if (x.won && Game.CountsAsAchievementOwned(x.pool)) a++; }
    Game.AchievementsOwned = a;
  }

  // A golden cookie "building special" on Nothing must not reach the game's save.
  // The game restores buffs while it loads, before any mod has added its building, and
  // an unknown building there stops it mid-load (the page never finishes starting).
  // These buffs last half a minute, so leaving them out of the save costs nothing.
  function keepBuildingBuffsOutOfSave() {
    const originalWriteSave = Game.WriteSave;
    Game.WriteSave = function () {
      const hidden = [];
      try {
        for (const k in Game.buffs) {
          const b = Game.buffs[k];
          // arg1 is the power, arg2 the building
          if (b && b.type && me && (b.type.name === 'building buff' || b.type.name === 'building debuff') && +b.arg2 === me.id) {
            hidden.push([b, b.type]);
            b.type = { name: b.type.name, vanilla: 0 };
          }
        }
      } catch (e) { report('save filter', e); }
      try { return originalWriteSave.apply(this, arguments); }
      finally { for (const [b, t] of hidden) b.type = t; }
    };
  }

  const mod = {
    init: function () {
      keepBuildingBuffsOutOfSave();
      const originalEarn = Game.Earn;
      Game.Earn = function (howmuch) {
        if (decaying) { if (Game.OnAscend) decaying = false; else return; }
        return originalEarn.call(this, howmuch);
      };
      Game.registerHook('logic', guard('logic', onLogic));
      Game.registerHook('reset', guard('reset', function (hard) {
        warnedThisRun = false; decaying = false; stats.above150 = 0;
        if (hard) stats = freshStats();
      }));
      Game.registerHook('ticker', guard('ticker', function () {
        if (!me || me.amount <= 0) return [];
        return TICKER.slice();
      }, []));
    },
    save: guard('save', function () {
      if (!me) return;
      return JSON.stringify({
        v: 3,
        b: [me.amount, me.bought, Math.floor(me.totalCookies), me.level, me.muted ? 1 : 0, me.highest],
        u: ourUpgrades.map(u => (u.unlocked ? 1 : 0) + (u.bought ? 2 : 0)),
        a: ourAchievements.map(a => (a.won ? 1 : 0)),
        s: stats,
      });
    }),
    load: guard('load', function (str) {
      if (!me || !str) return;
      let d;
      try { d = JSON.parse(str); } catch (e) { console.warn(TAG + ' Could not read saved data.', e); return; }
      if (d.b) {
        me.amount = d.b[0] | 0; me.bought = d.b[1] | 0; me.totalCookies = +d.b[2] || 0;
        me.level = d.b[3] | 0; me.highest = d.b[5] | 0;
        me.mute(d.b[4] ? 1 : 0);
      }
      (d.u || []).forEach(function (f, i) { if (ourUpgrades[i]) { ourUpgrades[i].unlocked = f & 1 ? 1 : 0; ourUpgrades[i].bought = f & 2 ? 1 : 0; } });
      (d.a || []).forEach(function (f, i) { if (ourAchievements[i]) ourAchievements[i].won = f ? 1 : 0; });
      if (d.s) stats = Object.assign(freshStats(), d.s);
      recount();
      me.pics = [];
      me.refresh();
      if (me.buyFunction) me.buyFunction();
      updateOdds();
      checkUnlocks();
      Game.recalculateGains = 1; Game.upgradesToRebuild = 1; Game.storeToRefresh = 1;
    }),
    _acceptRisk: function () { warnedThisRun = true; },
    // for testing from the console
    phage: function (type) { return phageStrikes(type); },
    decay: function () { return vacuumDecay(); },
    odds: function () { updateOdds(); return Object.assign({}, odds); },
    stats: function () { return Object.assign({}, stats); },
  };

  const waitForGame = setInterval(function () {
    if (!(window.Game && Game.ready && Game.Object && Game.ObjectsById && Game.ObjectsById.length >= 20 && document.getElementById('products'))) return;
    clearInterval(waitForGame);
    const unshim = cookieMonsterLoaded() ? shimCookieMonster(NAME) : null;
    try {
      if (!create()) { if (unshim) unshim(); return; }
    } catch (e) {
      if (unshim) unshim();
      console.error(TAG + ' Failed to load:', e);
      return;
    }
    registerWhenSafe(function () {
      if (unshim) unshim();
      try {
        Game.registerMod(MOD_ID, mod);
        updateOdds();
        console.log(TAG + ' The ultimate ensemble has an edge, and you have found it. Nothing is now for sale.');
      } catch (e) {
        console.error(TAG + ' Failed to load:', e);
      }
    });
  }, 250);
})();

// ---- art ------------------------------------------------------------------
// Art for the Nothing building, generated by make_art.py (original pixel art, embedded as PNG data).
window.__NOTHING_ART = {
 "row": "data:image/png;base64,",
 "bg": "data:image/png;base64,",
 "store": "data:image/png;base64,",
 "icons": "data:image/png;base64,"
};
